private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return  str == suffix;
    }
    if (ignoreCase) {
        return str.toUpperCase().endsWith(suffix.toUpperCase());
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == suffix;
    }
    int len = str.length() - suffix.length();
    if (ignoreCase) {
        return str.substring(len).toLowerCase().equals(suffix.toLowerCase());
    } else {
        return str.substring(len).equals(suffix);
    }
}

